/**
 * What `.strutvane/types/models.d.ts` (generated by spike 10) augments: the table registry.
 * Kept at the `#strutvane/model` path so spike 10's generated file works unchanged.
 *
 * ```ts
 * // generated
 * declare module "#strutvane/model" { interface TableRegistry extends Tables {} }
 * ```
 */
export { Model, type ModelClass, type ModelInstance, type ModelStatics } from './database/model.ts'

/**
 * Any value JSON can hold. Used by generated types for `t.json(…)` columns.
 *
 * @example
 * const meta: JsonValue = { pinned: true }
 */
export type JsonValue = string | number | boolean | null | JsonValue[] | { [key: string]: JsonValue }

/**
 * Every table in the app, with its four shapes. Empty here; the generated `models.d.ts` fills it
 * through declaration merging, so the framework never imports app code.
 *
 * @example
 * // after generation: TableRegistry['posts']['row'] is the Post row type
 */
export interface TableRegistry {}

/**
 * The name of any table the migrations created.
 *
 * @example
 * const table: TableName = 'posts' // 'post' would not compile
 */
export type TableName = keyof TableRegistry & string

/**
 * A row of a table as the model sees it (timestamps as `Date`).
 *
 * @example
 * type PostRow = RowOf<'posts'>
 */
export type RowOf<TTable extends TableName> = TableRegistry[TTable] extends { row: infer TRow } ? TRow : never

/**
 * What creating a row accepts.
 *
 * @example
 * const draft: InsertOf<'posts'> = { title: 'Hello', author_id: 1 }
 */
export type InsertOf<TTable extends TableName> = TableRegistry[TTable] extends { insert: infer TInsert } ? TInsert : never

/**
 * What updating a row accepts.
 *
 * @example
 * const patch: PatchOf<'posts'> = { title: 'New title' }
 */
export type PatchOf<TTable extends TableName> = TableRegistry[TTable] extends { update: infer TPatch } ? TPatch : never

/**
 * A row as the JSON API returns it (hidden columns removed, dates as strings).
 *
 * @example
 * type PostJson = JsonOf<'posts'>
 */
export type JsonOf<TTable extends TableName> = TableRegistry[TTable] extends { json: infer TJson } ? TJson : never
